/* Nepal Information Hub — Research lab › Research workflow.
   A guided, step-by-step empirical study (with a to-do list) that can be run on any series: NEPSE prices, your uploaded
   Excel/CSV (Date, Open, High, Low, Close, Volume + any extra variables), your quant series or any dataset column.
   Each step explains why it is done, runs the test, interprets the result and plots it. Results export to Excel and to a
   Word/HTML write-up. Numerics in research-core.js (RSC). */
'use strict';
const RS = {src: 'stock', sym: 'NEPSE', series: '', ds: '', col: '', cat: '', upload: null, opt: {windows: '30, 60, 90, 120', main: 60, kmax: 10, split: 80, hac: 5, h: 5, volW: 20}, extraSel: [], R: null, key: null, busy: false};
const RS_STEPS = [
  ['data', 'Data, validation and cleaning', 'Check dates, duplicates, missing values and whether every High ≥ Open, Close ≥ Low. A study is only as good as its data: one bad row can create a fake crash or a fake fractal spike.'],
  ['vars', 'Derived variables', 'Log return r = 100·ln(Pₜ/Pₜ₋₁) is additive over time and close to stationary; squared and absolute returns proxy volatility; rolling volatility, intraday range, open-to-close return and log volume add context; future return and future realised volatility are the targets for the forecasting tests (they use only later data, so they are never used as inputs).'],
  ['desc', 'Descriptive statistics and normality', 'Mean, spread, skewness and excess kurtosis describe the return distribution. Jarque–Bera tests normality: real markets usually fail it (fat tails), which is why Student-t errors are used later.'],
  ['stat', 'Stationarity (ADF, Phillips–Perron, KPSS)', 'ADF and Phillips–Perron test H₀ “unit root” (non-stationary); KPSS tests the opposite H₀ “stationary”. Prices are expected to have a unit root and returns not — that tells you to model returns, not price levels.'],
  ['acf', 'Autocorrelation and volatility clustering', 'The ACF and Ljung–Box test check whether returns are predictable from their own past. The same tests on squared returns, and Engle’s ARCH-LM test, detect volatility clustering: calm and turbulent days come in runs.'],
  ['fd', 'Fractal dimension (Higuchi)', 'The Higuchi fractal dimension D measures how rough a curve is: 1 = smooth line, 1.5 = random walk, 2 = pure noise. It is computed for the whole sample, in rolling windows, for several k_max values (sensitivity), with the log–log scaling plot (a straight line confirms scaling) and sanity checks on a straight line, white noise and a random walk.'],
  ['fdp', 'Fractal dimension of returns vs log price', 'Returns are almost noise, so their D sits near 2 and barely moves. The D of the log-price path varies through time (below 1.5 = persistent / trending, above 1.5 = anti-persistent / choppy) — that is the version that can carry information.'],
  ['dir', 'Does it predict direction? (models M0–M3)', 'Chronological split (first part to fit, last part kept untouched to test). M0 = average return, M1 = today’s return, M2 = + volatility and volume, M3 = + fractal dimension. OLS with Newey–West (HAC) standard errors, AIC/BIC, then out-of-sample RMSE/MAE, hit rate and a Diebold–Mariano test.'],
  ['vol', 'Does it predict volatility? (models V1–V3)', 'Same discipline for the size of moves: V1 = current volatility, V2 = + squared return and volume, V3 = + fractal dimension. In-sample fit is only the first hurdle; the out-of-sample test decides.'],
  ['garch', 'GARCH benchmark and fractal-augmented tests', 'GARCH(1,1) with Student-t errors is the industry standard. Two tests of extra information: an ARCH-LM style regression of squared standardised GARCH residuals on the lagged fractal dimension, and GARCH-X with the fractal term inside the variance equation (likelihood-ratio test). Then GARCH volatility forecasts are compared out of sample with V3.'],
  ['rob', 'Robustness across windows', 'Re-run the volatility model with every rolling window. A real effect should not depend on one arbitrary window choice.'],
  ['hurst', 'Cross-check with the Hurst exponent', 'An independent long-memory measure. For a self-affine path D ≈ 2 − H, so H > 0.5 (persistence) should go with lower fractal dimension.'],
  ['dd', 'Drawdowns and calendar returns', 'How deep and how long the market has fallen from its peaks, and the year-by-year returns — the numbers readers and risk managers ask for first.'],
  ['out', 'Write-up and export', 'Download every variable and result table to Excel, and a Word / HTML write-up with the charts, ready to edit into a report or article.']];
const RS_NEXT = ['Out-of-sample volatility forecast test (pending result)', 'Head-to-head with GARCH(1,1), with and without the fractal term', 'Robustness across 30 / 90 / 120-day windows', 'Cross-check against the Hurst exponent', 'Position-sizing rule from the volatility forecast (risk management, not a trading signal)', 'Repeat on sector indices and on large stocks'];
const rsF = (v, d = 3) => isNum(v) ? fmt(v, d) : '–', rsP = p => !isNum(p) ? '–' : p < 0.001 ? '<0.001' : fmt(p, 3), rsStar = p => !isNum(p) ? '' : p < 0.01 ? '***' : p < 0.05 ? '**' : p < 0.1 ? '*' : '';
const rsTbl = (head, rows, cls = '') => `<div class="tbl ${cls}"><table><thead><tr>${head.map((h, i) => `<th${i ? '' : ' class="txt"'}>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map((c, i) => `<td class="${i ? 'num' : 'txt'}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;

/* ---------- data sources ---------- */
function rsLoad() {
  if (RS.src === 'stock') { const S = priceSeries(RS.sym); if (S.c.length < 150) throw new Error('Not enough price history for ' + RS.sym); const vOk = S.v.some(v => isNum(v) && v > 0); return {name: RS.sym + ' (stock market prices)', key: 'stock:' + RS.sym, date: S.date, o: S.o, h: S.h, l: S.l, c: S.c, v: vOk ? S.v : null}; }
  if (RS.src === 'series') { const S = qSeries(RS.series); if (S.c.length < 150) throw new Error('Choose one of your series with at least 150 values.'); const vOk = S.v.some(v => isNum(v) && v !== 1); return {name: RS.series + ' (your series)', key: 'series:' + RS.series, date: S.date, o: S.o, h: S.h, l: S.l, c: S.c, v: vOk ? S.v : null}; }
  if (RS.src === 'dataset') { const d = ds(RS.ds); if (!d) throw new Error('Choose a dataset.'); const fq = freqOf(d), rows = d.rows.filter(r => (!catKeys(d).length || catLabel(d, r) === RS.cat) && isNum(r[RS.col]) && r[RS.col] > 0).map(r => ({date: qsKeyDate(fq, alignKey(d, r)), c: r[RS.col]})).filter(r => r.date).sort((a, b) => a.date < b.date ? -1 : 1);
    if (rows.length < 150) throw new Error(`Only ${rows.length} positive values in that column; the study needs at least 150 (use a daily or long monthly series).`); const col = d.cols.find(c => c.k === RS.col)?.label || RS.col; return {name: `${d.title} — ${col}${RS.cat ? ' · ' + RS.cat : ''}`, key: `ds:${d.id}:${RS.col}:${RS.cat}`, date: rows.map(r => r.date), c: rows.map(r => r.c), o: null, h: null, l: null, v: null}; }
  if (RS.src === 'upload') { if (!RS.upload) throw new Error('Upload an Excel or CSV file first (Date, Close required).'); return RS.upload; }
  throw new Error('Choose a data source.');
}
function rsParseAoa(aoa, name) {
  const H = aoa.findIndex(r => r.some(c => /^(date|business date|trade date|period)$/i.test(String(c ?? '').trim()))); if (H < 0) throw new Error('No "Date" column found in the first rows.');
  const h = aoa[H].map(c => String(c ?? '').trim()), low = h.map(x => x.toLowerCase()), ix = (...re) => low.findIndex(x => re.some(r => r.test(x)));
  const iD = ix(/^(date|business date|trade date|period)$/), iC = ix(/^(close|closing price|close price|closing|price|ltp|value|rate|adj close)$/), iO = ix(/^open/), iHi = ix(/^high/), iL = ix(/^low/), iV = ix(/^(volume|vol|traded quantity|qty)$/), iS = ix(/^(symbol|series|scrip)$/);
  if (iC < 0) throw new Error('No closing-price column (Close, Closing Price, Price, LTP, Value or Rate).');
  const num = v => { if (typeof v === 'number') return v; const x = parseNum(String(v ?? '').replace(/[^\d.,eE+-]/g, '')); return isNum(x) ? x : null; }, used = new Set([iD, iC, iO, iHi, iL, iV, iS]);
  const extraIdx = h.map((_, j) => j).filter(j => !used.has(j) && h[j] && aoa.slice(H + 1, H + 40).filter(r => isNum(num(r[j]))).length >= 10);
  const rows = aoa.slice(H + 1).map(r => ({d: cellDate(r[iD]), c: num(r[iC]), o: iO >= 0 ? num(r[iO]) : null, h: iHi >= 0 ? num(r[iHi]) : null, l: iL >= 0 ? num(r[iL]) : null, v: iV >= 0 ? num(r[iV]) : null, x: extraIdx.map(j => num(r[j]))})).filter(r => r.d && isNum(r.c) && r.c > 0).sort((a, b) => a.d < b.d ? -1 : 1);
  if (rows.length < 150) throw new Error(`Only ${rows.length} rows with a valid date and a positive close; the study needs at least 150.`);
  const extra = {}; extraIdx.forEach((j, k) => { const nm = h[j].replace(/[^A-Za-z0-9_]+/g, '_').replace(/^_|_$/g, '') || 'X' + (k + 1); let lastV = null; extra[nm] = rows.map(r => { if (isNum(r.x[k])) lastV = r.x[k]; return lastV; }); });
  return {name: name + ' (uploaded)', key: 'upload:' + name, date: rows.map(r => r.d), c: rows.map(r => r.c), o: iO >= 0 ? rows.map(r => r.o ?? r.c) : null, h: iHi >= 0 ? rows.map(r => r.h ?? r.c) : null, l: iL >= 0 ? rows.map(r => r.l ?? r.c) : null, v: iV >= 0 ? rows.map(r => r.v) : null, extra, extraNames: Object.keys(extra)};
}
/* the sample workbook: real NEPSE OHLCV rows + two optional extra variables, a variable dictionary and instructions */
function rsSampleWorkbook() {
  if (!window.XLSX) throw new Error('The spreadsheet library did not load.');
  const S = priceSeries('NEPSE'), rates = ds('rates_monthly'), fx = ds('fx_monthly'), monthMap = (d, col) => { const m = new Map(); (d?.rows || []).forEach(r => { const dt = qsKeyDate(freqOf(d), alignKey(d, r)); if (dt && isNum(r[col])) m.set(dt.slice(0, 7), r[col]); }); return m; };
  const ib = monthMap(rates, 'interbank'), fxc = fx ? (fx.cols.find(c => c.t === 'num') || {}).k : null, usd = fxc ? monthMap(fx, fxc) : new Map();
  const data = [['Date', 'Open', 'High', 'Low', 'Close', 'Volume', 'Interbank_Rate', 'USD_NPR'], ...S.date.map((d, i) => [d, S.o[i], S.h[i], S.l[i], S.c[i], S.v[i], ib.get(d.slice(0, 7)) ?? null, usd.get(d.slice(0, 7)) ?? null])];
  const vars = [['Variable', 'Required?', 'Type', 'Description', 'Example'], ['Date', 'Required', 'Date (AD)', 'Trading date, one row per day (or month). 2025-07-16, 16/07/2025 or an Excel date.', S.date[0]], ['Close', 'Required', 'Number > 0', 'Closing price / index value (also accepted: Closing Price, Price, LTP, Value, Rate).', S.c[0]], ['Open', 'Optional', 'Number', 'Opening price — enables the open-to-close return and OHLC checks.', S.o[0]], ['High', 'Optional', 'Number', 'Day high — enables the intraday range and OHLC checks.', S.h[0]], ['Low', 'Optional', 'Number', 'Day low.', S.l[0]], ['Volume', 'Optional', 'Number', 'Traded quantity or value — enables log volume as a control variable.', S.v[0]], ['Interbank_Rate, USD_NPR, …', 'Optional', 'Number', 'Any extra numeric column is read as an extra explanatory variable (monthly values may be repeated for each day; blanks are filled forward). Tick it under “Extra variables” to add it to the models.', ''], ['Symbol / Series', 'Optional', 'Text', 'If present, only the first series in the file is studied.', 'NEPSE']];
  const der = [['Derived variable', 'Formula', 'Used in'], ['Return', '100 × ln(Closeₜ / Closeₜ₋₁)', 'all tests'], ['Squared_Return', 'Return²', 'volatility clustering, V2/V3'], ['Absolute_Return', '|Return|', 'correlations'], ['Volatility_20', 'standard deviation of the last 20 returns', 'M2/M3, V1–V3'], ['Range', '(High − Low) / Close', 'context'], ['Open_Close_Return', '(Close − Open) / Open', 'context'], ['Log_Volume', 'ln(1 + Volume)', 'M2/M3, V2/V3'], ['Log_Close', 'ln(Close)', 'fractal dimension of price'], ['FD_w', 'Higuchi fractal dimension of returns over the last w days (k_max = 10, or w/6 for short windows)', 'fractal analysis'], ['FDPrice_w', 'Higuchi fractal dimension of Log_Close over the last w days', 'M3, V3, GARCH-X, robustness'], ['Future_Return_1', 'next day’s return', 'target of M0–M3'], ['Future_Return_5', 'sum of the next 5 returns', 'correlations'], ['Future_Volatility_5', 'standard deviation of the next 5 returns', 'target of V1–V3, GARCH comparison'], ['Drawdown', '100 × (Close / running maximum − 1)', 'drawdowns']];
  const how = [['How to use this file'], ['1. Keep the column names in row 1. Date and Close are required; the rest are optional.'], ['2. Paste your own data under the headers (at least 150 rows; 500+ recommended for rolling 60–120-day windows).'], ['3. In the app: Research lab › Research workflow › Upload Excel / CSV, choose this file, tick any extra variables, press Run the study.'], ['4. Every step shows the test, an explanation, the interpretation and charts; “Download results (Excel)” exports all variables and tables.'], ['5. Extra variables must be known on the date of the row. A monthly figure published mid-month should only appear from its publication date (shift it one month if unsure) — otherwise the forecast test uses information that was not yet available.'], ['Sample data: NEPSE index daily OHLCV from the app’s seed data; Interbank_Rate and USD_NPR are monthly NRB values repeated for each day of the month.']];
  const wb = XLSX.utils.book_new(); [['Data', data], ['Variables', vars], ['Derived variables', der], ['How to use', how]].forEach(([n, a]) => { const ws = XLSX.utils.aoa_to_sheet(a); ws['!cols'] = a[0].map((_, j) => ({wch: j === 3 ? 70 : 18})); XLSX.utils.book_append_sheet(wb, ws, n); });
  return wb;
}

/* ---------- plan persistence ---------- */
function rsPlan(key) { Store.db.research = Store.db.research || {}; const P = Store.db.research[key] = Store.db.research[key] || {steps: {}, tasks: RS_NEXT.map(t => ({t, done: false}))}; return P; }
let rsSaveT = null; const rsSave = () => { clearTimeout(rsSaveT); rsSaveT = setTimeout(() => persist(true), 600); };

/* ---------- page ---------- */
function renderResearch() {
  const p = $('#p-study'), syms = symbols(), mine = qsCustom(), dsList = allDs().filter(d => d.id !== QS_DS && freqOf(d) && numCols(d).length && d.rows.length > 30), o = RS.opt;
  p.innerHTML = `<div class="card wide"><div class="chead"><div><h2>Research workflow</h2><p class="sub">A complete empirical study, step by step, on any series — the pipeline of a published NEPSE fractal-dimension study turned into a reusable to-do list: validate data → derive variables → pre-tests → fractal dimension → direction and volatility forecasting with a strict out-of-sample test → GARCH benchmark → robustness → drawdowns → write-up. Every step explains <i>why</i>, runs the test, interprets the result and plots it.</p></div></div>
    <div class="subnav" id="rsSrc">${[['stock', 'Stock market prices'], ['upload', 'Upload Excel / CSV'], ['series', 'My quant series'], ['dataset', 'Any dataset column']].map(([k, l]) => `<button data-s="${k}" aria-selected="${RS.src === k}">${l}</button>`).join('')}</div>
    <div class="form" style="grid-template-columns:repeat(auto-fit,minmax(170px,1fr));margin-top:10px">
      ${RS.src === 'stock' ? `<div class="f"><label for="rsSym">Symbol</label><select id="rsSym">${syms.map(s => `<option ${s === RS.sym ? 'selected' : ''}>${esc(s)}</option>`).join('')}</select></div>` : ''}
      ${RS.src === 'series' ? `<div class="f"><label for="rsSer">Series</label><select id="rsSer">${mine.length ? mine.map(s => `<option ${s === RS.series ? 'selected' : ''}>${esc(s)}</option>`).join('') : '<option value="">(none yet — add under Quant lab)</option>'}</select></div>` : ''}
      ${RS.src === 'dataset' ? `<div class="f"><label for="rsDs">Dataset</label><select id="rsDs">${uniq(dsList.map(d => d.group)).map(g => `<optgroup label="${esc(g)}">${dsList.filter(d => d.group === g).map(d => `<option value="${esc(d.id)}" ${d.id === RS.ds ? 'selected' : ''}>${esc(d.title)}</option>`).join('')}</optgroup>`).join('')}</select></div><div class="f"><label for="rsCol">Column</label><select id="rsCol"></select></div><div class="f"><label for="rsCat">Category</label><select id="rsCat"></select></div>` : ''}
      ${RS.src === 'upload' ? `<div class="f" style="grid-column:span 2"><label for="rsFile">Excel / CSV file (Date, Close required; Open, High, Low, Volume and extra variables optional)</label><input id="rsFile" type="file" accept=".xlsx,.xls,.csv,.txt"></div>` : ''}
      <div class="f"><label for="rsWin">Fractal windows (days)</label><input id="rsWin" value="${esc(o.windows)}"></div><div class="f"><label for="rsMain">Main window</label><input id="rsMain" value="${o.main}"></div><div class="f"><label for="rsKmax">k_max</label><input id="rsKmax" value="${o.kmax}"></div><div class="f"><label for="rsSplit">Training share %</label><input id="rsSplit" value="${o.split}"></div><div class="f"><label for="rsHac">HAC lags</label><input id="rsHac" value="${o.hac}"></div><div class="f"><label for="rsH">Forecast horizon (days)</label><input id="rsH" value="${o.h}"></div><div class="f"><label for="rsVolW">Volatility window</label><input id="rsVolW" value="${o.volW}"></div></div>
    ${RS.upload?.extraNames?.length && RS.src === 'upload' ? `<div class="sub" style="margin:6px 0">Extra variables in the file — tick to add them to models M2/M3 and V2/V3: ${RS.upload.extraNames.map(n => `<label style="margin-right:10px"><input type="checkbox" data-ex="${esc(n)}" ${RS.extraSel.includes(n) ? 'checked' : ''}> ${esc(n)}</label>`).join('')}</div>` : ''}
    <div class="actions"><button class="btn primary" id="rsRun">Run the study</button><button class="btn small" id="rsSample">Download sample Excel (variables)</button><button class="btn small" id="rsTpl">Blank template</button><span id="rsMsg">${RS.upload && RS.src === 'upload' ? `Loaded ${esc(RS.upload.name)}: ${RS.upload.date.length} rows` : ''}</span></div></div>
    <div id="rsPlan"></div><div id="rsOut" style="display:grid;gap:18px"></div>`;
  $('#rsSrc').onclick = e => { const b = e.target.closest('button'); if (!b) return; RS.src = b.dataset.s; RS.R = null; renderResearch(); };
  if ($('#rsSym')) $('#rsSym').onchange = e => { RS.sym = e.target.value; RS.R = null; rsDrawPlan(); $('#rsOut').innerHTML = ''; };
  if ($('#rsSer')) $('#rsSer').onchange = e => { RS.series = e.target.value; RS.R = null; };
  if ($('#rsDs')) { const fill = () => { RS.ds = $('#rsDs').value; const d = ds(RS.ds); $('#rsCol').innerHTML = numCols(d).map(c => `<option value="${esc(c.k)}" ${c.k === RS.col ? 'selected' : ''}>${esc(c.label)}</option>`).join(''); RS.col = $('#rsCol').value; const cats = catKeys(d).length ? uniq(d.rows.map(r => catLabel(d, r))) : []; $('#rsCat').innerHTML = cats.length ? cats.map(c => `<option ${c === RS.cat ? 'selected' : ''}>${esc(c)}</option>`).join('') : '<option value="">(none)</option>'; RS.cat = $('#rsCat').value; };
    if (!RS.ds) RS.ds = $('#rsDs').value; fill(); $('#rsDs').onchange = () => { RS.col = ''; RS.cat = ''; fill(); }; $('#rsCol').onchange = e => { RS.col = e.target.value; }; $('#rsCat').onchange = e => { RS.cat = e.target.value; }; }
  if ($('#rsFile')) $('#rsFile').onchange = async e => { const f = e.target.files[0]; if (!f) return; try { const sh = await parseFileBuffer(f.name, await f.arrayBuffer()); const aoa = sh.find(s => s.aoa && s.aoa.length > 20)?.aoa; if (!aoa) throw new Error('No data sheet found.'); RS.upload = rsParseAoa(aoa, f.name.replace(/\.[^.]+$/, '')); RS.extraSel = []; RS.R = null; renderResearch(); } catch (er) { msg('#rsMsg', er.message, 'err'); } };
  p.querySelectorAll('[data-ex]').forEach(cb => cb.onchange = () => { RS.extraSel = [...p.querySelectorAll('[data-ex]:checked')].map(x => x.dataset.ex); });
  $('#rsSample').onclick = () => { try { XLSX.writeFile(rsSampleWorkbook(), 'Research_Sample_NEPSE.xlsx'); } catch (e) { msg('#rsMsg', e.message, 'err'); } };
  $('#rsTpl').onclick = () => { const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([['Date', 'Open', 'High', 'Low', 'Close', 'Volume', 'Extra_Variable_1'], ['2025-07-16', '', '', '', '', '', '']]), 'Data'); XLSX.writeFile(wb, 'Research_Template.xlsx'); };
  $('#rsRun').onclick = () => rsRun();
  rsDrawPlan();
  if (RS.R) rsDraw();
}
function rsReadOpt() { const o = RS.opt, n = (id, d) => { const v = parseFloat($(id).value); return isFinite(v) && v > 0 ? v : d; }; o.windows = $('#rsWin').value; o.main = Math.round(n('#rsMain', 60)); o.kmax = Math.round(n('#rsKmax', 10)); o.split = Math.min(95, Math.max(50, n('#rsSplit', 80))); o.hac = Math.round(n('#rsHac', 5)); o.h = Math.max(2, Math.round(n('#rsH', 5))); o.volW = Math.max(5, Math.round(n('#rsVolW', 20))); }
async function rsRun() {
  if (RS.busy) return; rsReadOpt(); msg('#rsMsg', 'Running all steps…'); RS.busy = true; await new Promise(r => setTimeout(r, 30));
  try { const D = rsLoad(), o = RS.opt, wins = String(o.windows).split(/[,\s]+/).map(Number).filter(w => w >= 20 && w <= 500).sort((a, b) => a - b); if (!wins.length) throw new Error('Give at least one window of 20 days or more.'); if (!wins.includes(o.main)) wins.push(o.main), wins.sort((a, b) => a - b);
    if (D.c.length < Math.max(...wins) + 120) throw new Error(`The series has ${D.c.length} rows; with a ${Math.max(...wins)}-day window it needs at least ${Math.max(...wins) + 120}. Use shorter windows.`);
    const t0 = performance.now(); RS.R = RSC.run(D, {windows: wins, main: o.main, kmax: o.kmax, split: o.split / 100, hac: o.hac, h: o.h, volW: o.volW, extra: RS.src === 'upload' ? RS.extraSel : [], ppy: periodsPerYear(D.date)}); RS.R.D = D; RS.R.ms = performance.now() - t0; RS.key = D.key;
    msg('#rsMsg', `Done in ${fmt(RS.R.ms / 1000, 1)} s: ${D.name}, ${D.c.length} rows.`); rsDrawPlan(); rsDraw(); } catch (e) { if (/undefined|not a function|null/.test(e.message)) console.error(e); msg('#rsMsg', e.message, 'err'); }
  RS.busy = false;
}

/* ---------- interpretation ---------- */
function rsFindings(R) {
  const F = {}, FDm = `FDPrice_${R.opt.main}`, m3 = R.dir.M3.m, j3 = m3.coef.length - 1, v3 = R.vol.V3.m, jv = v3.coef.length - 1;
  F.data = R.qc.dup || R.qc.missing.close || R.qc.hiLo ? ['check the data', `${R.qc.dup} duplicate dates, ${R.qc.missing.close} missing closes${isNum(R.qc.hiLo) ? `, ${R.qc.hiLo} rows with High < Low` : ''} — check the source.`] : ['clean', `${R.qc.rows} rows from ${R.qc.start} to ${R.qc.end}; no duplicates or missing closes${isNum(R.qc.hiOpen) && (R.qc.hiOpen + R.qc.hiClose) ? `; ${R.qc.hiOpen + R.qc.hiClose} rows where High is below Open/Close (data-vendor rounding — usually harmless)` : ''}.`];
  F.vars = ['built', `${Object.keys(R.V).length - 1} variables built for ${R.n} return observations.`];
  F.desc = [R.desc.jbP < 0.05 ? 'fat tails' : 'close to normal', `Average daily return ${rsF(R.desc.mean, 4)}% with standard deviation ${rsF(R.desc.sd)}% (annualised volatility ≈ ${rsF(R.desc.annVol, 1)}%). Skewness ${rsF(R.desc.skew, 2)}, excess kurtosis ${rsF(R.desc.kurt, 2)}; Jarque–Bera ${R.desc.jbP < 0.05 ? 'rejects normality (fat tails) — use t-distributed errors' : 'does not reject normality'}.`];
  F.stat = [R.adfP.p > 0.05 && R.adfR.p < 0.05 ? 'price I(1), returns I(0)' : 'check stationarity', `Price: ADF p = ${rsP(R.adfP.p)}, PP p = ${rsP(R.ppP.p)} → ${R.adfP.p > 0.05 ? 'unit root (non-stationary)' : 'stationary'}. Returns: ADF p = ${rsP(R.adfR.p)}, PP p = ${rsP(R.ppR.p)} → ${R.adfR.p < 0.05 ? 'stationary — model returns, not prices' : 'not stationary — check the data'}.`];
  const lb10 = R.lbR.find(x => x.L === 10) || R.lbR[0], lbs = R.lbS.find(x => x.L === 10) || R.lbS[0];
  F.acf = [R.arch.p < 0.05 ? 'volatility clusters' : 'no clustering', `Returns ${lb10.p < 0.05 ? 'show some serial correlation' : 'show no significant serial correlation'} (Ljung–Box(${lb10.L}) p = ${rsP(lb10.p)}). Squared returns: Ljung–Box p = ${rsP(lbs.p)}, ARCH-LM(${R.opt.archL}) p = ${rsP(R.arch.p)} → ${R.arch.p < 0.05 ? 'strong volatility clustering: a turbulent day tends to be followed by more turbulence' : 'no volatility clustering detected'}.`];
  F.fd = ['D(returns) = ' + rsF(R.fdFull.D), `Full-sample Higuchi D of returns = ${rsF(R.fdFull.D)} (R² of the log–log fit ${rsF(R.fdFull.r2, 4)}): ${R.fdFull.D > 1.9 ? 'close to 2 — returns are almost noise' : 'below noise level'}. Across k_max ${R.kmaxSens[0]?.k}–${last(R.kmaxSens)?.k} it stays between ${rsF(Math.min(...R.kmaxSens.map(x => x.ret)))} and ${rsF(Math.max(...R.kmaxSens.map(x => x.ret)))}. Sanity checks: straight line ${rsF(R.sanity.line)}, white noise ${rsF(R.sanity.noise)}, random walk ${rsF(R.sanity.walk)} — the method behaves as theory says.`];
  const sP = R.fdStats.find(x => x.k === FDm), sR = R.fdStats.find(x => x.k === `FD_${R.opt.main}`);
  F.fdp = ['D(log price) = ' + rsF(R.fdPrice.D), `Log-price D = ${rsF(R.fdPrice.D)} for the full sample; the rolling ${R.opt.main}-day log-price D averages ${rsF(sP?.mean)} and ranges ${rsF(sP?.min, 2)}–${rsF(sP?.max, 2)} (s.d. ${rsF(sP?.sd)}), while the return D stays near ${rsF(sR?.mean, 2)} (s.d. ${rsF(sR?.sd)}). Only the price-based measure moves enough to be informative.`];
  const dAic = m3.aic - R.dir.M2.m.aic, oosBetter = R.dir.M3.rmse < R.dir.M0.rmse;
  F.dir = [m3.pz[j3] < 0.05 && oosBetter ? 'direction signal' : 'no direction signal', `R²: M1 ${rsF(R.dir.M1.m.r2 * 100, 1)}%, M2 ${rsF(R.dir.M2.m.r2 * 100, 1)}%, M3 ${rsF(m3.r2 * 100, 1)}%. The fractal coefficient in M3 is ${rsF(m3.coef[j3])} (p = ${rsP(m3.pz[j3])}) — ${m3.pz[j3] < 0.05 ? 'significant' : 'not significant'}; AIC ${dAic < 0 ? 'improves' : 'gets worse'} by ${rsF(Math.abs(dAic), 1)}. Out of sample, RMSE M0 ${rsF(R.dir.M0.rmse)} vs M3 ${rsF(R.dir.M3.rmse)} (Diebold–Mariano p = ${rsP(R.dir.dm30.p)}); hit rate ${rsF(R.dir.M3.hit * 100, 1)}%. ${m3.pz[j3] < 0.05 && oosBetter ? 'Some directional information.' : 'Knowing the fractal dimension does not help predict tomorrow’s direction.'}`];
  const vIn = v3.pz[jv] < 0.05, vOut = R.vol.V3.rmse < R.vol.V2.rmse;
  F.vol = [vIn && vOut ? 'helps in and out of sample' : vIn ? 'in-sample only' : 'no volatility signal', `In sample: adjusted R² V1 ${rsF(R.vol.V1.m.adjR2 * 100, 1)}% → V2 ${rsF(R.vol.V2.m.adjR2 * 100, 1)}% → V3 ${rsF(v3.adjR2 * 100, 1)}%; fractal coefficient ${rsF(v3.coef[jv])} (p = ${rsP(v3.pz[jv])}) — ${vIn ? (v3.coef[jv] < 0 ? 'significant and negative: rougher price paths precede calmer volatility' : 'significant and positive') : 'not significant'}. Out of sample: RMSE V2 ${rsF(R.vol.V2.rmse)} vs V3 ${rsF(R.vol.V3.rmse)} (Diebold–Mariano p = ${rsP(R.vol.dm32.p)}) → ${vOut ? 'the fractal term improves real forecasts' : 'the in-sample gain does not survive the out-of-sample test'}.`];
  const g = R.garch, fdA = g.archFd, jf = fdA.coef.length - 1;
  F.garch = [fdA.pz[jf] < 0.05 || g.lrP < 0.05 ? 'adds to GARCH' : 'nothing beyond GARCH', `GARCH(1,1)-t: α = ${rsF(g.base.alpha)}, β = ${rsF(g.base.beta)} (persistence ${rsF(g.base.alpha + g.base.beta)}), ν = ${rsF(g.base.nu, 2)}. Lagged fractal dimension in the ARCH-LM regression of squared standardised residuals: p = ${rsP(fdA.pz[jf])}; GARCH-X likelihood-ratio test: LR = ${rsF(g.lr, 2)}, p = ${rsP(g.lrP)} → ${fdA.pz[jf] < 0.05 || g.lrP < 0.05 ? 'adds information beyond GARCH' : 'no extra information beyond GARCH'}. Out-of-sample ${R.opt.h}-day volatility RMSE: GARCH ${rsF(g.oos.rmseB)}, GARCH-X ${rsF(g.oos.rmseX)}, V3 ${rsF(R.vol.V3.rmse)}.`];
  const sig = R.robust.rows.filter(x => x.p < 0.05).length, beat = R.robust.rows.filter(x => x.rmse < R.robust.ref.rmse).length;
  F.rob = [`${sig}/${R.robust.rows.length} significant, ${beat}/${R.robust.rows.length} beat OOS`, `${sig} of ${R.robust.rows.length} windows give a significant fractal coefficient in sample; ${beat} of ${R.robust.rows.length} beat the no-fractal model out of sample (reference RMSE ${rsF(R.robust.ref.rmse)}).`];
  const hr = R.hurst.roll, pr = R.V[FDm].map((v, i) => [v, hr[i]]).filter(x => isNum(x[0]) && isNum(x[1])), cH = pr.length > 30 ? ST.corr(pr.map(x => x[0]), pr.map(x => x[1])) : null;
  F.hurst = ['H = ' + rsF(R.hurst.full.H), `Hurst exponent of returns (R/S) = ${rsF(R.hurst.full.H)}, Anis–Lloyd corrected ${rsF(R.hurst.full.Hal)}, DFA α = ${rsF(R.hurst.dfa.alpha)} → ${R.hurst.full.Hal > 0.55 ? 'some persistence' : R.hurst.full.Hal < 0.45 ? 'anti-persistence' : 'close to a random walk'}. Correlation between rolling ${R.hurst.w}-day H and the ${R.opt.main}-day log-price D: ${rsF(cH, 2)} (theory expects a negative sign).`]; F.hurstCorr = cH;
  F.dd = ['max drawdown ' + rsF(R.dd.max, 1) + '%', `Deepest drawdown ${rsF(R.dd.max, 1)}% (trough ${R.dd.maxDate}); now ${rsF(R.dd.current, 1)}% below the peak, ${rsF(R.dd.sinceTrough, 1)}% above the trough.`];
  F.out = ['ready', 'Export the variables and tables to Excel and the write-up to Word / HTML.'];
  return F;
}

/* ---------- to-do list ---------- */
function rsDrawPlan() {
  const box = $('#rsPlan'); if (!box) return; let key = RS.key; try { key = rsLoad().key; } catch (e) {} if (!key) { box.innerHTML = ''; return; } const P = rsPlan(key), F = RS.R && RS.key === key ? rsFindings(RS.R) : null;
  box.innerHTML = `<div class="card wide"><div class="chead"><div><h2>Research plan (to-do)</h2><p class="sub">Steps tick themselves when the study runs and show their result; mark each one reviewed and keep notes — saved with your data. Add your own tasks below.</p></div></div>
    <div class="tbl"><table><thead><tr><th class="txt">#</th><th class="txt">Step</th><th class="txt">Status</th><th class="txt">Result</th><th class="txt">Reviewed</th><th class="txt">Notes</th></tr></thead><tbody>${RS_STEPS.map(([id, nm], i) => { const st = F?.[id]; const s = P.steps[id] || {}; return `<tr><td class="txt">${i + 1}</td><td class="txt"><a href="#rs-${id}" data-go="${id}">${nm}</a></td><td class="txt">${st ? (st[0] === 'check the data' ? '<span class="warnc">! check</span>' : '<span class="okc">✓ done</span>') : '<span class="sub">pending</span>'}</td><td class="txt">${st ? esc(st[0]) : ''}</td><td class="txt"><input type="checkbox" data-rev="${id}" ${s.rev ? 'checked' : ''} aria-label="Reviewed ${esc(nm)}"></td><td class="txt"><input data-note="${id}" value="${esc(s.note || '')}" placeholder="note…" style="width:100%;min-width:180px"></td></tr>`; }).join('')}</tbody></table></div>
    <h3>My research tasks</h3><div id="rsTasks">${P.tasks.map((t, i) => `<div style="display:flex;gap:8px;align-items:center;margin:4px 0"><input type="checkbox" data-td="${i}" ${t.done ? 'checked' : ''} aria-label="Done"><input data-tt="${i}" value="${esc(t.t)}" style="flex:1"><button class="btn small" data-tx="${i}" aria-label="Delete task">×</button></div>`).join('')}</div>
    <div class="actions"><button class="btn small" id="rsAddT">+ Add task</button><span class="sub">${P.tasks.filter(t => t.done).length} of ${P.tasks.length} tasks done</span></div></div>`;
  box.querySelectorAll('[data-rev]').forEach(cb => cb.onchange = () => { (P.steps[cb.dataset.rev] = P.steps[cb.dataset.rev] || {}).rev = cb.checked; rsSave(); });
  box.querySelectorAll('[data-note]').forEach(inp => inp.onchange = () => { (P.steps[inp.dataset.note] = P.steps[inp.dataset.note] || {}).note = inp.value; rsSave(); });
  box.querySelectorAll('[data-td]').forEach(cb => cb.onchange = () => { P.tasks[+cb.dataset.td].done = cb.checked; rsSave(); rsDrawPlan(); });
  box.querySelectorAll('[data-tt]').forEach(inp => inp.onchange = () => { P.tasks[+inp.dataset.tt].t = inp.value; rsSave(); });
  box.querySelectorAll('[data-tx]').forEach(b => b.onclick = () => { P.tasks.splice(+b.dataset.tx, 1); rsSave(); rsDrawPlan(); });
  $('#rsAddT').onclick = () => { P.tasks.push({t: 'New task', done: false}); rsSave(); rsDrawPlan(); };
  box.querySelectorAll('[data-go]').forEach(a => a.onclick = e => { e.preventDefault(); const el = document.getElementById('rs-' + a.dataset.go); if (el) el.scrollIntoView({behavior: 'smooth'}); else toast('Run the study first.'); });
}

/* ---------- results ---------- */
function rsDraw() {
  const R = RS.R, V = R.V, F = rsFindings(R), t = T(), o = R.opt, FDm = `FDPrice_${o.main}`, VW = `Volatility_${o.volW}`, FV = `Future_Volatility_${o.h}`, dates = V.Date;
  const step = (id, inner) => { const i = RS_STEPS.findIndex(s => s[0] === id), [, nm, why] = RS_STEPS[i], f = F[id]; return `<div class="card wide" id="rs-${id}"><div class="chead"><div><h2>Step ${i + 1} · ${nm} ${f ? `<span class="chip ${f[0] === 'check the data' ? 'dn' : 'nt'}">${esc(f[0])}</span>` : ''}</h2></div></div><details class="panel"><summary><span>Learn: why this step and how to read it</span></summary><div><p class="sub">${why}</p></div></details>${f ? `<p class="rsfind"><b>Finding:</b> ${f[1]}</p>` : ''}${inner}</div>`; };
  const cv = (id, title, cls = '') => `<div><h3>${title}</h3><div class="cv ${cls}"><canvas id="${id}"></canvas></div></div>`, mt = (m, names) => rsTbl(['Variable', 'Coefficient', 'HAC s.e.', 'z', 'p', ''], m.coef.map((c, i) => [names[i], rsF(c, 4), rsF(m.se[i], 4), rsF(m.z[i], 2), rsP(m.pz[i]), rsStar(m.pz[i])]));
  const qc = R.qc, mods = ['M1', 'M2', 'M3'].map(k => R.dir[k]), vmods = ['V1', 'V2', 'V3'].map(k => R.vol[k]);
  $('#rsOut').innerHTML = `<div class="card wide"><h2>${esc(R.D.name)}: summary of findings</h2><div class="kpis" id="rsK"></div><ul class="rsul">${RS_STEPS.slice(2, 12).map(([id, nm]) => `<li><b>${nm}:</b> ${F[id][1]}</li>`).join('')}</ul>
      <div class="actions"><button class="btn primary small" id="rsXlsx">Download results (Excel)</button><button class="btn small" id="rsDoc">Download write-up (Word)</button><button class="btn small" id="rsHtml">Download write-up (HTML)</button><button class="btn small" id="rsSaveV">Save variables as a dataset</button></div></div>
    ${step('data', rsTbl(['Check', 'Result'], [['Rows / period', `${qc.rows} · ${qc.start} → ${qc.end}`], ['Duplicate dates', qc.dup], ['Missing closes', qc.missing.close], ...(isNum(qc.hiLo) ? [['High < Low', qc.hiLo], ['High < Open', qc.hiOpen ?? '–'], ['High < Close', qc.hiClose], ['Low > Open', qc.loOpen ?? '–'], ['Low > Close', qc.loClose]] : [['OHLC checks', 'no High/Low columns']]), ['Non-positive values', Object.entries(qc.nonPos).map(([k, v]) => `${{o: 'Open', h: 'High', l: 'Low', c: 'Close', v: 'Volume'}[k]} ${v}`).join(', ')]]) + `<div class="grid2">${cv('rsC1', 'Closing price')}${cv('rsC2', 'Daily log returns (%)')}</div>`)}
    ${step('vars', `<div class="tbl scroll" style="max-height:300px"><table><thead><tr>${Object.keys(V).map(k => `<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${[...Array(6).keys()].map(i => i).concat([...Array(6).keys()].map(i => R.n - 6 + i)).map(i => `<tr>${Object.keys(V).map(k => `<td class="num">${typeof V[k][i] === 'string' ? V[k][i] : rsF(V[k][i], 4)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="sub">First and last six rows; the Excel download has every row.</p>`)}
    ${step('desc', rsTbl(['Mean', 'Median', 'Std. dev.', 'Min', 'Max', 'Skewness', 'Excess kurtosis', 'Jarque–Bera', 'p'], [[rsF(R.desc.mean, 4), rsF(R.desc.median, 4), rsF(R.desc.sd, 4), rsF(R.desc.min, 3), rsF(R.desc.max, 3), rsF(R.desc.skew, 3), rsF(R.desc.kurt, 3), rsF(R.desc.jb, 2), rsP(R.desc.jbP)]]) + `<div class="grid2">${cv('rsC3', 'Return distribution vs normal')}${cv('rsC4', 'Drawdown from running peak (%)')}</div>`)}
    ${step('stat', rsTbl(['Test (H₀)', 'Series', 'Statistic', 'p', 'Lags', '5% critical', 'Decision'], [['ADF (unit root)', 'Price', rsF(R.adfP.stat), rsP(R.adfP.p), R.adfP.lags, rsF(R.adfP.crit['5%']), R.adfP.p < 0.05 ? 'stationary' : 'unit root'], ['ADF (unit root)', 'Returns', rsF(R.adfR.stat), rsP(R.adfR.p), R.adfR.lags, rsF(R.adfR.crit['5%']), R.adfR.p < 0.05 ? 'stationary' : 'unit root'], ['Phillips–Perron (unit root)', 'Price', rsF(R.ppP.stat), rsP(R.ppP.p), R.ppP.lags, rsF(R.ppP.crit?.[1]), R.ppP.p < 0.05 ? 'stationary' : 'unit root'], ['Phillips–Perron (unit root)', 'Returns', rsF(R.ppR.stat), rsP(R.ppR.p), R.ppR.lags, rsF(R.ppR.crit?.[1]), R.ppR.p < 0.05 ? 'stationary' : 'unit root'], ...(R.kpssP ? [['KPSS (stationary)', 'Price', rsF(R.kpssP.stat), rsP(R.kpssP.p), R.kpssP.lags, rsF(R.kpssP.crit?.['5%']), R.kpssP.p < 0.05 ? 'not stationary' : 'stationary'], ['KPSS (stationary)', 'Returns', rsF(R.kpssR.stat), rsP(R.kpssR.p), R.kpssR.lags, rsF(R.kpssR.crit?.['5%']), R.kpssR.p < 0.05 ? 'not stationary' : 'stationary']] : [])]))}
    ${step('acf', rsTbl(['Test', 'Lags', 'Statistic', 'p'], [...R.lbR.map(x => ['Ljung–Box: returns', x.L, rsF(x.stat, 2), rsP(x.p)]), ...R.lbS.map(x => ['Ljung–Box: squared returns', x.L, rsF(x.stat, 2), rsP(x.p)]), [`ARCH-LM (LM)`, o.archL ?? 10, rsF(R.arch.lm, 2), rsP(R.arch.p)], ['ARCH-LM (F)', o.archL ?? 10, rsF(R.arch.F, 3), rsP(R.arch.Fp)]]) + `<div class="grid2">${cv('rsC5', 'ACF of returns (95% band)', 'short')}${cv('rsC6', 'ACF of squared returns', 'short')}</div>${cv('rsC7', 'Returns and squared returns: clustering')}`)}
    ${step('fd', `${rsTbl(['Measure', 'Value'], [['D of returns (full sample, k_max ' + o.kmax + ')', rsF(R.fdFull.D, 4)], ['R² of the log–log fit', rsF(R.fdFull.r2, 5)], ['D of log price', rsF(R.fdPrice.D, 4)], ['D of price level', rsF(R.fdLevel.D, 4)], ['Sanity: straight line (should be 1)', rsF(R.sanity.line, 4)], ['Sanity: white noise (≈ 2)', rsF(R.sanity.noise, 4)], ['Sanity: random walk (≈ 1.5)', rsF(R.sanity.walk, 4)]])}
      ${rsTbl(['Rolling series', 'Obs', 'Mean', 'Std', 'Min', '25%', 'Median', '75%', 'Max'], R.fdStats.map(s => [s.k, s.n, rsF(s.mean, 4), rsF(s.sd, 4), rsF(s.min, 3), rsF(s.q25, 3), rsF(s.med, 3), rsF(s.q75, 3), rsF(s.max, 3)]), 'scroll')}
      <div class="grid2">${cv('rsC8', 'Higuchi log–log scaling: log L(k) vs log(1/k)')}${cv('rsC9', 'Sensitivity to k_max')}</div>${cv('rsC10', 'Rolling fractal dimension of returns (all windows)')}`)}
    ${step('fdp', `<div class="grid2">${cv('rsC11', `Rolling ${o.main}-day D: log price vs returns`)}${cv('rsC12', `Log-price D (${o.main}d) vs next ${o.h}-day volatility`)}</div><h3>Correlations</h3>${[R.corr1, R.corr2].map(C => rsTbl(['', ...C.cols], C.m.map((row, a) => [C.cols[a], ...row.map(v => `<span style="background:rgba(${v >= 0 ? '42,120,214' : '208,59,59'},${Math.min(0.45, Math.abs(v) * 0.45)});padding:1px 4px;border-radius:3px">${rsF(v, 3)}</span>`)]), 'scroll')).join('')}`)}
    ${step('dir', `<p class="sub">Training ${R.split.train} rows (${R.split.trainFrom} → ${R.split.trainTo}); test ${R.split.test} rows (${R.split.testFrom} → ${R.split.testTo}). HAC lags ${o.hac}.</p>
      ${rsTbl(['Model', 'Regressors', 'R²', 'Adj. R²', 'AIC', 'BIC', 'OOS RMSE', 'OOS MAE', 'Hit rate'], [['M0', 'training mean', '', '', '', '', rsF(R.dir.M0.rmse, 4), rsF(R.dir.M0.mae, 4), ''], ...mods.map(x => [x.name, x.cols.join(', '), rsF(x.m.r2 * 100, 2) + '%', rsF(x.m.adjR2 * 100, 2) + '%', rsF(x.m.aic, 1), rsF(x.m.bic, 1), rsF(x.rmse, 4), rsF(x.mae, 4), rsF(x.hit * 100, 1) + '%'])], 'scroll')}
      <p class="sub">Diebold–Mariano (squared error): M3 vs M1 stat ${rsF(R.dir.dm31.stat, 2)}, p = ${rsP(R.dir.dm31.p)}; M3 vs M0 p = ${rsP(R.dir.dm30.p)}. Positive statistic = M3 worse.</p><h3>M3 coefficients</h3>${mt(R.dir.M3.m, ['Constant', ...R.dir.M3.cols])}${cv('rsC13', 'Next-day return: actual vs M3 forecast (test period)')}`)}
    ${step('vol', `${rsTbl(['Model', 'Regressors', 'R²', 'Adj. R²', 'AIC', 'BIC', 'OOS RMSE', 'OOS MAE'], vmods.map(x => [x.name, x.cols.join(', '), rsF(x.m.r2 * 100, 2) + '%', rsF(x.m.adjR2 * 100, 2) + '%', rsF(x.m.aic, 1), rsF(x.m.bic, 1), rsF(x.rmse, 4), rsF(x.mae, 4)]), 'scroll')}
      <p class="sub">Diebold–Mariano V3 vs V2 (h = ${o.h}): stat ${rsF(R.vol.dm32.stat, 2)}, p = ${rsP(R.vol.dm32.p)}.</p><div class="grid2"><div><h3>V2 coefficients</h3>${mt(R.vol.V2.m, ['Constant', ...R.vol.V2.cols])}</div><div><h3>V3 coefficients</h3>${mt(R.vol.V3.m, ['Constant', ...R.vol.V3.cols])}</div></div>${cv('rsC14', `Future ${o.h}-day volatility: actual vs V2, V3 and GARCH (test period)`)}`)}
    ${step('garch', `${rsTbl(['Model', 'μ', 'ω', 'α', 'β', 'ν (t)', 'γ (fractal)', 'Log-lik.', 'AIC', 'BIC'], [['GARCH(1,1)-t', rsF(R.garch.base.mu, 4), rsF(R.garch.base.omega, 4), rsF(R.garch.base.alpha, 4), rsF(R.garch.base.beta, 4), rsF(R.garch.base.nu, 3), '', rsF(R.garch.base.ll, 2), rsF(R.garch.base.aic, 2), rsF(R.garch.base.bic, 2)], ['GARCH-X (fractal in variance)', rsF(R.garch.x.mu, 4), rsF(R.garch.x.omega, 4), rsF(R.garch.x.alpha, 4), rsF(R.garch.x.beta, 4), rsF(R.garch.x.nu, 3), rsF(R.garch.x.gamma, 4), rsF(R.garch.x.ll, 2), rsF(R.garch.x.aic, 2), rsF(R.garch.x.bic, 2)]], 'scroll')}
      <p class="sub">Likelihood-ratio test γ = 0: LR = ${rsF(R.garch.lr, 3)}, p = ${rsP(R.garch.lrP)}. The fractal term enters standardised (z-score of the lagged ${o.main}-day log-price D).</p><h3>ARCH-LM style test: squared standardised residual on its lag and lagged D</h3>${mt(R.garch.archFd, ['Constant', 'Lag 1', `${FDm} (lag 1)`])}
      ${rsTbl([`Out-of-sample ${o.h}-day volatility (${R.garch.oos.n} test days)`, 'RMSE', 'MAE'], [['V2 (no fractal)', rsF(R.vol.V2.rmse, 4), rsF(R.vol.V2.mae, 4)], ['V3 (with fractal)', rsF(R.vol.V3.rmse, 4), rsF(R.vol.V3.mae, 4)], ['GARCH(1,1)-t', rsF(R.garch.oos.rmseB, 4), rsF(R.garch.oos.maeB, 4)], ['GARCH-X', rsF(R.garch.oos.rmseX, 4), rsF(R.garch.oos.maeX, 4)]])}${cv('rsC15', 'GARCH conditional volatility (%) and absolute returns')}`)}
    ${step('rob', rsTbl(['Window', 'Coefficient', 'p', 'Adj. R²', 'AIC', 'OOS RMSE', 'OOS MAE', 'Beats V2?'], [['V2 reference (no fractal)', '', '', rsF(R.robust.ref.adjR2 * 100, 2) + '%', rsF(R.robust.ref.aic, 1), rsF(R.robust.ref.rmse, 4), rsF(R.robust.ref.mae, 4), ''], ...R.robust.rows.map(x => [x.w + ' days', rsF(x.coef, 4), rsP(x.p) + ' ' + rsStar(x.p), rsF(x.adjR2 * 100, 2) + '%', rsF(x.aic, 1), rsF(x.rmse, 4), rsF(x.mae, 4), x.rmse < R.robust.ref.rmse ? '<span class="okc">yes</span>' : '<span class="badc">no</span>'])]) + `<p class="sub">${R.robust.n} rows where every window exists (train ${R.robust.train}, test ${R.robust.test}).</p>${cv('rsC16', 'Out-of-sample RMSE by window (line = model without fractal)', 'short')}`)}
    ${step('hurst', rsTbl(['Measure', 'Value'], [['Hurst R/S (returns)', rsF(R.hurst.full.H, 4)], ['Anis–Lloyd corrected H', rsF(R.hurst.full.Hal, 4)], ['DFA α', rsF(R.hurst.dfa.alpha, 4)], [`Corr(rolling ${R.hurst.w}-day H, ${FDm})`, rsF(F.hurstCorr, 3)]]) + `<div class="grid2">${cv('rsC17', `Rolling Hurst exponent (${R.hurst.w}-day)`)}${cv('rsC18', 'Log-price D vs 2 − H')}</div>`)}
    ${step('dd', `<div class="grid2"><div>${rsTbl(['Start (peak)', 'Trough', 'Recovered', 'Depth', 'Days'], R.dd.episodes.map(e => [e.start, e.trough, e.recovered ? e.end : 'not yet', rsF(e.depth, 2) + '%', e.days]))}</div><div>${rsTbl(['Year', 'Last close', 'Return'], R.dd.yearly.map(y => [y.y, rsF(y.close, 2), isNum(y.ret) ? rsF(y.ret, 2) + '%' : '–']))}</div></div>${cv('rsC19', 'Calendar-year returns (%)', 'short')}`)}
    ${step('out', '<p class="sub">Use the buttons in the summary card at the top. The Excel file holds every variable (one row per day) and every result table; the write-up follows the steps with the charts embedded.</p>')}`;
  kpis('#rsK', [{k: 'Observations', v: String(R.n)}, {k: 'Return D (full)', v: rsF(R.fdFull.D)}, {k: `Log-price D (${o.main}d avg)`, v: rsF(R.fdStats.find(x => x.k === FDm)?.mean)}, {k: 'Direction: FD p (M3)', v: rsP(R.dir.M3.m.pz[R.dir.M3.m.coef.length - 1]), dir: 'nt'}, {k: 'Volatility: FD p (V3)', v: rsP(R.vol.V3.m.pz[R.vol.V3.m.coef.length - 1])}, {k: 'OOS RMSE V3 vs V2', v: `${rsF(R.vol.V3.rmse)} / ${rsF(R.vol.V2.rmse)}`, dir: R.vol.V3.rmse < R.vol.V2.rmse ? 'up' : 'dn'}]);
  const L = dates, lc = (id, ds2, opts = {}) => mk(id, {type: 'line', data: {labels: opts.labels || L, datasets: ds2}, options: Object.assign({plugins: {tooltip: tip('', 3)}, scales: {x: xCat(8)}}, opts.o || {})});
  lc('rsC1', [line('Close', V.Close, t.s[0], {borderWidth: 1.5})]); lc('rsC2', [line('Return %', V.Return, t.s[1], {borderWidth: 1})]);
  const H = omHist(V.Return, 50), m = R.desc.mean, s = R.desc.sd; omXY('rsC3', [sl('empirical density', xy(H.x, H.dens), t.s[0], {stepped: 'middle', fill: 'origin', backgroundColor: t.s[0] + '22'}), sl('normal', xy(H.x, H.x.map(x => Math.exp(-0.5 * ((x - m) / s) ** 2) / (s * Math.sqrt(2 * Math.PI)))), t.crit, {borderDash: [5, 4]})], {xt: 'return %', yt: 'density', d: 3});
  lc('rsC4', [line('Drawdown %', V.Drawdown, t.crit, {fill: 'origin', backgroundColor: t.crit + '22', borderWidth: 1})]);
  const band = 1.96 / Math.sqrt(R.n), acfC = (id, a) => mk(id, {type: 'bar', data: {labels: a.map((_, i) => i), datasets: [bar('ACF', a.map((v, i) => i ? v : null), a.map(v => Math.abs(v) > band ? t.crit : t.s[0]), {maxBarThickness: 8}), line('+95%', a.map(() => band), t.ink3, {type: 'line', borderDash: [4, 3], borderWidth: 1}), line('−95%', a.map(() => -band), t.ink3, {type: 'line', borderDash: [4, 3], borderWidth: 1})]}, options: {plugins: {legend: {display: false}, tooltip: tip('', 3)}, scales: {x: {grid: {display: false}, ticks: {maxTicksLimit: 10}}}}});
  acfC('rsC5', R.acfR); acfC('rsC6', R.acfS);
  lc('rsC7', [line('Return', V.Return, t.s[0], {borderWidth: 1}), line('Squared return', V.Squared_Return, t.s[3], {borderWidth: 1, yAxisID: 'y2'})], {o: {plugins: {tooltip: tip('', 3)}, scales: {x: xCat(8), y: {}, y2: {position: 'right', grid: {display: false}}}}});
  const d = R.fdFull; omXY('rsC8', [sp('log L(k)', d.lx.map((x, i) => ({x, y: d.ly[i]})), t.s[0], {pointRadius: 5}), sl(`fit: slope D = ${fmt(d.D, 4)}, R² = ${fmt(d.r2, 4)}`, [Math.min(...d.lx), Math.max(...d.lx)].map(x => ({x, y: d.intercept + d.D * x})), t.crit)], {xt: 'log(1/k)', yt: 'log L(k)', d: 3});
  mk('rsC9', {type: 'line', data: {labels: R.kmaxSens.map(x => x.k), datasets: [line('Returns', R.kmaxSens.map(x => x.ret), t.s[0], {pointRadius: 3}), line('Log price', R.kmaxSens.map(x => x.price), t.s[1], {pointRadius: 3, yAxisID: 'y2'})]}, options: {plugins: {tooltip: tip('', 4)}, scales: {x: {grid: {display: false}, title: {display: true, text: 'k_max', color: t.ink3}}, y: {}, y2: {position: 'right', grid: {display: false}}}}});
  lc('rsC10', [...o.windows.map((w, i) => line(`FD ${w}d`, V[`FD_${w}`], t.s[i % 8], {borderWidth: 1.2})), line('1.5', L.map(() => 1.5), t.ink3, {borderDash: [5, 4], borderWidth: 1})]);
  lc('rsC11', [line(`Log price D (${o.main}d)`, V[FDm], t.s[0], {borderWidth: 1.4}), line(`Returns D (${o.main}d)`, V[`FD_${o.main}`], t.s[1], {borderWidth: 1.4}), line('1.5 = random walk', L.map(() => 1.5), t.ink3, {borderDash: [5, 4], borderWidth: 1})]);
  const scat = V[FDm].map((v, i) => ({x: v, y: V[FV][i]})).filter(p => isNum(p.x) && isNum(p.y)), sf = scat.length > 10 ? ST.ols(scat.map(p => p.y), scat.map(p => [1, p.x])) : null, xr = [Math.min(...scat.map(p => p.x)), Math.max(...scat.map(p => p.x))];
  omXY('rsC12', [sp('day', scat, t.s[0] + '99', {pointRadius: 1.8}), ...(sf ? [sl(`OLS slope ${fmt(sf.coef[1], 3)}`, xr.map(x => ({x, y: sf.coef[0] + sf.coef[1] * x})), t.crit)] : [])], {xt: `log-price D (${o.main}d)`, yt: `next ${o.h}-day volatility`, d: 3});
  const te = R.dir.M3, teDates = dates.slice(-te.pred.length); mk('rsC13', {type: 'line', data: {labels: R.split.testDates, datasets: [line('Actual', te.pred.map((p, i) => p + te.err[i]), t.ink3, {borderWidth: 1}), line('M3 forecast', te.pred, t.s[0], {borderWidth: 2})]}, options: {plugins: {tooltip: tip('', 3)}, scales: {x: xCat(8)}}});
  const vd = R.split.testDates, gmap = new Map(R.garch.oos.dates.map((dd, i) => [dd, R.garch.oos.predB[i]]));
  mk('rsC14', {type: 'line', data: {labels: vd, datasets: [line('Actual', R.vol.V3.pred.map((p, i) => p + R.vol.V3.err[i]), t.ink3, {borderWidth: 1}), line('V2', R.vol.V2.pred, t.s[1], {borderWidth: 1.5}), line('V3 (+FD)', R.vol.V3.pred, t.s[0], {borderWidth: 2}), line('GARCH', vd.map(dd => gmap.get(dd) ?? null), t.s[3], {borderWidth: 1.5, borderDash: [4, 3]})]}, options: {plugins: {tooltip: tip('', 3)}, scales: {x: xCat(8)}}});
  mk('rsC15', {type: 'line', data: {labels: R.garch.dates, datasets: [line('|return|', R.garch.dates.map((dd, i) => Math.abs(V.Return[dates.indexOf(dd)])), t.ink3 + '88', {borderWidth: 0.8}), line('GARCH σ', R.garch.base.s2.map(Math.sqrt), t.crit, {borderWidth: 1.8})]}, options: {plugins: {tooltip: tip('', 3)}, scales: {x: xCat(8)}}});
  mk('rsC16', {type: 'bar', data: {labels: R.robust.rows.map(x => x.w + 'd'), datasets: [bar('OOS RMSE with fractal', R.robust.rows.map(x => x.rmse), R.robust.rows.map(x => x.rmse < R.robust.ref.rmse ? t.good : t.s[1])), line('V2 (no fractal)', R.robust.rows.map(() => R.robust.ref.rmse), t.crit, {type: 'line', borderDash: [5, 4]})]}, options: {plugins: {tooltip: tip('', 4)}, scales: {x: {grid: {display: false}}, y: {beginAtZero: false}}}});
  lc('rsC17', [line('Rolling H', R.hurst.roll, t.s[2], {borderWidth: 1.3}), line('0.5', L.map(() => 0.5), t.ink3, {borderDash: [5, 4], borderWidth: 1})]);
  const hp = V[FDm].map((v, i) => ({x: 2 - R.hurst.roll[i], y: v})).filter(p => isNum(p.x) && isNum(p.y)); omXY('rsC18', [sp('day', hp, t.s[4] + '99', {pointRadius: 1.8})], {xt: '2 − H (rolling)', yt: `log-price D (${o.main}d)`, legend: false, d: 3});
  const yr = R.dd.yearly.filter(y => isNum(y.ret)); mk('rsC19', {type: 'bar', data: {labels: yr.map(y => y.y), datasets: [bar('Return %', yr.map(y => y.ret), yr.map(y => y.ret >= 0 ? t.good : t.crit))]}, options: {plugins: {legend: {display: false}, tooltip: tip('%', 2)}, scales: {x: {grid: {display: false}}}}});
  $('#rsXlsx').onclick = () => rsExcel(R, F); $('#rsDoc').onclick = () => rsReport(R, F, 'doc'); $('#rsHtml').onclick = () => rsReport(R, F, 'html');
  $('#rsSaveV').onclick = async () => { const cols = Object.keys(V).filter(k => k !== 'Date'), id = 'my_research_' + Date.now().toString(36); Store.db.datasets[id] = {id, title: `Research variables — ${R.D.name} ${new Date().toISOString().slice(0, 10)}`, group: 'My data', period: 'date', cols: [{k: 'date', label: 'Date', t: 'date', key: true}, ...cols.map((c, i) => ({k: 'v' + i, label: c, t: 'num'}))], rows: V.Date.map((dd, i) => Object.assign({date: dd}, ...cols.map((c, j) => ({['v' + j]: isNum(V[c][i]) ? +V[c][i].toPrecision(10) : null})))), keys: ['date'], source: 'Research workflow', unit: '', custom: true}; logChange('Saved research variables', id, R.D.name); await persist(true); afterDataChange(); toast('Saved under All data › My data — usable in Data analysis, Compare and Quant lab.'); };
}

/* ---------- exports ---------- */
function rsExcel(R, F) {
  const wb = XLSX.utils.book_new(), add = (n, a) => { const ws = XLSX.utils.aoa_to_sheet(a); ws['!cols'] = (a[0] || []).map(() => ({wch: 16})); XLSX.utils.book_append_sheet(wb, ws, n.slice(0, 31)); }, V = R.V, keys = Object.keys(V), r6 = v => isNum(v) ? +v.toPrecision(10) : v ?? null;
  add('Summary', [['Study', R.D.name], ['Rows', R.n], ['Run', new Date().toISOString()], [], ['Step', 'Status', 'Finding'], ...RS_STEPS.map(([id, nm]) => [nm, F[id]?.[0] || '', F[id]?.[1] || ''])]);
  add('Variables', [keys, ...V.Date.map((_, i) => keys.map(k => r6(V[k][i])))]);
  add('Pre-tests', [['Test', 'Series', 'Statistic', 'p-value', 'Lags'], ['Jarque–Bera', 'Returns', R.desc.jb, R.desc.jbP, ''], ['ADF', 'Price', R.adfP.stat, R.adfP.p, R.adfP.lags], ['ADF', 'Returns', R.adfR.stat, R.adfR.p, R.adfR.lags], ['Phillips–Perron', 'Price', R.ppP.stat, R.ppP.p, R.ppP.lags], ['Phillips–Perron', 'Returns', R.ppR.stat, R.ppR.p, R.ppR.lags], ...(R.kpssP ? [['KPSS', 'Price', R.kpssP.stat, R.kpssP.p, R.kpssP.lags], ['KPSS', 'Returns', R.kpssR.stat, R.kpssR.p, R.kpssR.lags]] : []), ...R.lbR.map(x => ['Ljung–Box', 'Returns', x.stat, x.p, x.L]), ...R.lbS.map(x => ['Ljung–Box', 'Squared returns', x.stat, x.p, x.L]), ['ARCH-LM', 'Returns', R.arch.lm, R.arch.p, 10], [], ['Descriptive', 'Mean', 'Median', 'SD', 'Min', 'Max', 'Skew', 'Excess kurtosis'], ['Returns', R.desc.mean, R.desc.median, R.desc.sd, R.desc.min, R.desc.max, R.desc.skew, R.desc.kurt]]);
  add('Fractal', [['Measure', 'Value'], ['D returns', R.fdFull.D], ['R2 log-log', R.fdFull.r2], ['D log price', R.fdPrice.D], ['Sanity line', R.sanity.line], ['Sanity noise', R.sanity.noise], ['Sanity walk', R.sanity.walk], [], ['k_max', 'D returns', 'D log price'], ...R.kmaxSens.map(x => [x.k, x.ret, x.price]), [], ['Series', 'N', 'Mean', 'SD', 'Min', 'Q25', 'Median', 'Q75', 'Max'], ...R.fdStats.map(s => [s.k, s.n, s.mean, s.sd, s.min, s.q25, s.med, s.q75, s.max])]);
  const modRows = (grp, list) => [[grp, 'Variable', 'Coefficient', 'HAC SE', 'z', 'p', 'R2', 'Adj R2', 'AIC', 'BIC', 'OOS RMSE', 'OOS MAE'], ...list.flatMap(x => x.m.coef.map((c, i) => [x.name, ['const', ...x.cols][i], c, x.m.se[i], x.m.z[i], x.m.pz[i], i ? '' : x.m.r2, i ? '' : x.m.adjR2, i ? '' : x.m.aic, i ? '' : x.m.bic, i ? '' : x.rmse, i ? '' : x.mae]))];
  add('Direction models', [...modRows('Model', [R.dir.M1, R.dir.M2, R.dir.M3]), [], ['M0 mean forecast', R.dir.M0.forecast, 'RMSE', R.dir.M0.rmse, 'MAE', R.dir.M0.mae], ['DM M3 vs M1', R.dir.dm31.stat, 'p', R.dir.dm31.p]]);
  add('Volatility models', [...modRows('Model', [R.vol.V1, R.vol.V2, R.vol.V3]), [], ['DM V3 vs V2', R.vol.dm32.stat, 'p', R.vol.dm32.p]]);
  add('GARCH', [['Model', 'mu', 'omega', 'alpha', 'beta', 'nu', 'gamma', 'loglik', 'AIC', 'BIC'], ['GARCH(1,1)-t', R.garch.base.mu, R.garch.base.omega, R.garch.base.alpha, R.garch.base.beta, R.garch.base.nu, '', R.garch.base.ll, R.garch.base.aic, R.garch.base.bic], ['GARCH-X', R.garch.x.mu, R.garch.x.omega, R.garch.x.alpha, R.garch.x.beta, R.garch.x.nu, R.garch.x.gamma, R.garch.x.ll, R.garch.x.aic, R.garch.x.bic], ['LR test', R.garch.lr, 'p', R.garch.lrP], [], ['ARCH-LM-FD', 'coef', 'HAC SE', 'p'], ...R.garch.archFd.coef.map((c, i) => [['const', 'lag1', 'FD lag'][i], c, R.garch.archFd.se[i], R.garch.archFd.pz[i]]), [], ['OOS', 'RMSE', 'MAE'], ['GARCH', R.garch.oos.rmseB, R.garch.oos.maeB], ['GARCH-X', R.garch.oos.rmseX, R.garch.oos.maeX]]);
  add('Robustness', [['Window', 'Coef', 'p', 'Adj R2', 'AIC', 'OOS RMSE', 'OOS MAE'], ['V2 reference', '', '', R.robust.ref.adjR2, R.robust.ref.aic, R.robust.ref.rmse, R.robust.ref.mae], ...R.robust.rows.map(x => [x.w, x.coef, x.p, x.adjR2, x.aic, x.rmse, x.mae])]);
  add('Drawdowns', [['Start', 'Trough', 'End', 'Depth %', 'Days'], ...R.dd.episodes.map(e => [e.start, e.trough, e.end || 'not recovered', e.depth, e.days]), [], ['Year', 'Close', 'Return %'], ...R.dd.yearly.map(y => [y.y, y.close, y.ret])]);
  const P = rsPlan(R.D.key); add('Research plan', [['Step', 'Status', 'Reviewed', 'Notes'], ...RS_STEPS.map(([id, nm]) => [nm, F[id]?.[0] || '', P.steps[id]?.rev ? 'yes' : '', P.steps[id]?.note || '']), [], ['Task', 'Done'], ...P.tasks.map(t => [t.t, t.done ? 'yes' : ''])]);
  XLSX.writeFile(wb, `Research_${R.D.name.replace(/[^A-Za-z0-9]+/g, '_').slice(0, 40)}.xlsx`);
}
function rsReport(R, F, kind) {
  const img = id => { const c = document.getElementById(id); try { return c ? `<img src="${c.toDataURL('image/png')}" style="width:640px;max-width:100%;border:1px solid #ddd">` : ''; } catch (e) { return ''; } }, o = R.opt;
  const fig = (id, cap) => `<p>${img(id)}<br><i>${cap}</i></p>`, sec = (h, id, figs = []) => `<h2>${h}</h2><p>${F[id][1]}</p>${figs.map(([c, cap]) => fig(c, cap)).join('')}`;
  const body = `<h1>${esc(R.D.name)}: an empirical study of roughness, returns and volatility</h1><p><i>Generated by Nepal Information Hub — Research workflow, ${new Date().toISOString().slice(0, 10)}. ${R.n} return observations, ${R.qc.start} to ${R.qc.end}. All findings are statistical results on historical data and should be validated before use.</i></p>
    ${sec('Data', 'data', [['rsC1', 'Figure 1 — Closing price.'], ['rsC2', 'Figure 2 — Daily log returns.']])}${sec('Return distribution', 'desc', [['rsC3', 'Figure 3 — Distribution of returns against the normal curve.']])}${sec('Stationarity', 'stat')}${sec('Volatility clustering', 'acf', [['rsC7', 'Figure 4 — Returns and squared returns.']])}
    ${sec('Fractal dimension', 'fd', [['rsC8', 'Figure 5 — Higuchi log–log scaling.'], ['rsC9', 'Figure 6 — Sensitivity to k_max.']])}${sec('Two fractal dimensions, two stories', 'fdp', [['rsC11', `Figure 7 — Rolling ${o.main}-day fractal dimension: log price vs returns.`]])}
    ${sec('Does it predict direction?', 'dir')}${sec('Volatility, not direction', 'vol', [['rsC12', 'Figure 8 — Fractal dimension against subsequent volatility.'], ['rsC14', 'Figure 9 — Out-of-sample volatility forecasts.']])}${sec('Against the GARCH benchmark', 'garch')}${sec('Robustness', 'rob', [['rsC16', 'Figure 10 — Out-of-sample error by window.']])}${sec('Hurst cross-check', 'hurst')}${sec('Drawdowns and yearly returns', 'dd', [['rsC4', 'Figure 11 — Drawdown from the running peak.'], ['rsC19', 'Figure 12 — Calendar-year returns.']])}
    <h2>What comes next</h2><ul>${rsPlan(R.D.key).tasks.map(t => `<li>${t.done ? '☑' : '☐'} ${esc(t.t)}</li>`).join('')}</ul><p><i>Method: Higuchi (1988) fractal dimension; OLS with Newey–West HAC (${o.hac} lags); chronological ${Math.round(o.split * 100)}/${100 - Math.round(o.split * 100)} train/test split; Diebold–Mariano tests; GARCH(1,1) with Student-t errors.</i></p>`;
  const html = `<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word"><head><meta charset="utf-8"><title>Research write-up</title><style>body{font-family:Calibri,Arial,sans-serif;max-width:760px;margin:30px auto;line-height:1.5;color:#222}h1{font-size:24px}h2{font-size:17px;margin-top:24px}</style></head><body>${body}</body></html>`;
  download(`Research_${R.D.name.replace(/[^A-Za-z0-9]+/g, '_').slice(0, 40)}.${kind === 'doc' ? 'doc' : 'html'}`, html, kind === 'doc' ? 'application/msword' : 'text/html');
}
